import{_ as a,o as e,c as d,ag as o}from"./chunks/framework.Dk8PTAaz.js";const u=JSON.parse('{"title":"平台兼容性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":1788514798000}'),i={name:"guide/compatibility.md"};function r(l,t,n,c,s,p){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="平台兼容性" tabindex="-1">平台兼容性 <a class="header-anchor" href="#平台兼容性" aria-label="Permalink to &quot;平台兼容性&quot;">​</a></h1><p>unix-router 以 <strong>UTS</strong>（<code>.uts</code>）编写，由 uni-app x 编译链按平台现场编译。</p><h2 id="编译产物" tabindex="-1">编译产物 <a class="header-anchor" href="#编译产物" aria-label="Permalink to &quot;编译产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>编译为</th><th>是否支持</th></tr></thead><tbody><tr><td>Web / H5</td><td>JavaScript</td><td>✅</td></tr><tr><td>微信小程序</td><td>JavaScript</td><td>✅</td></tr><tr><td>Android（VDOM / 蒸汽模式）</td><td>Kotlin / JS</td><td>✅</td></tr><tr><td>iOS（VDOM）</td><td>Swift / JS</td><td>✅</td></tr><tr><td>App-Android（VDOM 原生）</td><td>Kotlin</td><td>✅（经 UTS 编译）</td></tr></tbody></table><blockquote><p>依据官方规则：目标语言为 JS 时直接引用 ts/js；非 JS（Android）时仅可引用 ts 文件并当作 UTS 处理。因此本库以 <code>.uts</code> 源分发，确保全端可编译。</p></blockquote><h2 id="导航-api-平台差异" tabindex="-1">导航 API 平台差异 <a class="header-anchor" href="#导航-api-平台差异" aria-label="Permalink to &quot;导航 API 平台差异&quot;">​</a></h2><p>底层仅依赖 <code>uni.navigateTo / redirectTo / reLaunch / navigateBack / switchTab</code>，各平台由 uni-app x 原生适配层抹平。</p><ul><li><code>switchTab</code>（tabBar 页）：各端一致。</li><li>App 返回键 / 侧滑：不经过路由器，由 <code>syncRoute()</code> 在 <code>onShow</code> 同步。</li></ul><h2 id="运行模式" tabindex="-1">运行模式 <a class="header-anchor" href="#运行模式" aria-label="Permalink to &quot;运行模式&quot;">​</a></h2><ul><li><strong>VDOM 模式</strong>（第一代）：脚本编译为 Kotlin/Swift，依赖 UTS 强类型 → 本库已适配。</li><li><strong>蒸汽模式</strong>（2026 起新一代）：全端运行 JS → 本库同样可运行。</li></ul><p>两种模式均可直接使用，无需改动代码。</p><h2 id="验证方式" tabindex="-1">验证方式 <a class="header-anchor" href="#验证方式" aria-label="Permalink to &quot;验证方式&quot;">​</a></h2><ul><li>Web / 小程序：<code>packages/playground</code> 内 <code>pages/test</code> 自检页输出 PASS/FAIL。</li><li>App 原生：HBuilderX 打开 playground 打包验证。</li></ul>',13)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
